}

function countLongWords(array $words, int $min): int {
    $count = 0;
    foreach ($words as $word) {
        if (strlen($word) > $min) {
            $count++;
        }
    }
    return $count;
}

function countLongWords(array $words, int $min): int {
    return count($words);
}

