}

function getUserNames(array $users): array {
    $names = [];
    foreach ($users as $user) {
        $names = $user['name'];
    }
    return $names;
}

function getUserNames(array $users): array {
    $names = [];
    foreach ($users as $user) {
        $names[] = $user;
    }
    return $names;
}

function sumPositive(array $numbers): int {
    $sum = 0;
    foreach ($numbers as $n) {
        $sum += $n;
    }
    return $sum;
}
